insert into public.lessons (id, unit_id, sort_order, kind) values ('36fe0ddb-7536-5951-b174-f513bc850d15', (select u.id from public.units u join public.levels l on l.id = u.level_id join public.courses c on c.id = l.course_id where c.slug = 'english' and l.code = 'pre-a1' and u.slug = 'alphabet-and-sounds'), 1, 'lesson') on conflict (id) do update set sort_order = excluded.sort_order;
insert into public.lesson_translations (lesson_id, locale, title, grammar_tip, pronunciation_tip) values ('36fe0ddb-7536-5951-b174-f513bc850d15', 'vi', 'Chữ cái A đến G', 'Tiếng Anh có 26 chữ cái. Mỗi chữ có một cái tên riêng, khác với âm của nó trong từ. Khi đánh vần, người ta đọc tên chữ.', 'A đọc là "ây", không phải "a". E đọc là "i", không phải "e". Người Việt hay nhầm hai chữ này nhất.') on conflict (lesson_id, locale) do update set title = excluded.title, grammar_tip = excluded.grammar_tip, pronunciation_tip = excluded.pronunciation_tip, status = 'ok';
insert into public.lesson_translations (lesson_id, locale, title, grammar_tip, pronunciation_tip) values ('36fe0ddb-7536-5951-b174-f513bc850d15', 'en-US', 'Letters A to G', 'English has 26 letters. Each letter has a name. The name is different from its sound in a word. To spell a word, say the letter names.', 'A sounds like "ay". E sounds like "ee". Do not mix them up.') on conflict (lesson_id, locale) do update set title = excluded.title, grammar_tip = excluded.grammar_tip, pronunciation_tip = excluded.pronunciation_tip, status = 'ok';
