insert into public.lessons (id, unit_id, sort_order, kind) values ('05d9d295-6397-585d-9fc9-9844a1fd3014', (select u.id from public.units u join public.levels l on l.id = u.level_id join public.courses c on c.id = l.course_id where c.slug = 'english' and l.code = 'pre-a1' and u.slug = 'alphabet-and-sounds'), 2, 'lesson') on conflict (id) do update set sort_order = excluded.sort_order;
insert into public.lesson_translations (lesson_id, locale, title, grammar_tip, pronunciation_tip) values ('05d9d295-6397-585d-9fc9-9844a1fd3014', 'vi', 'Chữ cái H đến N', 'Để đánh vần tên mình, đọc lần lượt tên từng chữ cái. Ví dụ tên Minh: M, I, N, H.', 'I đọc là "ai", không phải "i". H đọc là "ết-ch", J đọc là "giây", K đọc là "kây".') on conflict (lesson_id, locale) do update set title = excluded.title, grammar_tip = excluded.grammar_tip, pronunciation_tip = excluded.pronunciation_tip, status = 'ok';
insert into public.lesson_translations (lesson_id, locale, title, grammar_tip, pronunciation_tip) values ('05d9d295-6397-585d-9fc9-9844a1fd3014', 'en-US', 'Letters H to N', 'To spell your name, say each letter name in order. For example, Minh: M, I, N, H.', 'I sounds like "eye". H is "aitch", J is "jay", K is "kay".') on conflict (lesson_id, locale) do update set title = excluded.title, grammar_tip = excluded.grammar_tip, pronunciation_tip = excluded.pronunciation_tip, status = 'ok';
