insert into public.lessons (id, unit_id, sort_order, kind) values ('e54cecfd-5adb-5f05-a3de-dcea9c2f7c6d', (select u.id from public.units u join public.levels l on l.id = u.level_id join public.courses c on c.id = l.course_id where c.slug = 'english' and l.code = 'pre-a1' and u.slug = 'alphabet-and-sounds'), 3, 'lesson') on conflict (id) do update set sort_order = excluded.sort_order;
insert into public.lesson_translations (lesson_id, locale, title, grammar_tip, pronunciation_tip) values ('e54cecfd-5adb-5f05-a3de-dcea9c2f7c6d', 'vi', 'Chữ cái O đến U', 'Khi người khác chưa nghe rõ tên bạn, hãy đánh vần chậm từng chữ.', 'R đọc là "a" kèm uốn lưỡi, không rung lưỡi như tiếng Việt. U đọc là "diu", Q đọc là "kiu".') on conflict (lesson_id, locale) do update set title = excluded.title, grammar_tip = excluded.grammar_tip, pronunciation_tip = excluded.pronunciation_tip, status = 'ok';
insert into public.lesson_translations (lesson_id, locale, title, grammar_tip, pronunciation_tip) values ('e54cecfd-5adb-5f05-a3de-dcea9c2f7c6d', 'en-US', 'Letters O to U', 'When people do not hear your name clearly, spell it slowly, one letter at a time.', 'R is "ar": curl your tongue back. U is "you", Q is "cue".') on conflict (lesson_id, locale) do update set title = excluded.title, grammar_tip = excluded.grammar_tip, pronunciation_tip = excluded.pronunciation_tip, status = 'ok';
