insert into public.lessons (id, unit_id, sort_order, kind) values ('7f7566e1-f570-5c82-82db-037878131bd1', (select u.id from public.units u join public.levels l on l.id = u.level_id join public.courses c on c.id = l.course_id where c.slug = 'english' and l.code = 'pre-a1' and u.slug = 'alphabet-and-sounds'), 4, 'lesson') on conflict (id) do update set sort_order = excluded.sort_order;
insert into public.lesson_translations (lesson_id, locale, title, grammar_tip, pronunciation_tip) values ('7f7566e1-f570-5c82-82db-037878131bd1', 'vi', 'Chữ cái V đến Z', 'Bạn đã biết đủ 26 chữ cái. Tiếng Anh không có dấu thanh, nên tên tiếng Việt được đánh vần không dấu: Việt là V, I, E, T.', 'W đọc là "đấp-bồ-diu" (nghĩa là hai chữ U). Y đọc là "oai". Z trong tiếng Anh Mỹ đọc là "di", môi rung nhẹ.') on conflict (lesson_id, locale) do update set title = excluded.title, grammar_tip = excluded.grammar_tip, pronunciation_tip = excluded.pronunciation_tip, status = 'ok';
insert into public.lesson_translations (lesson_id, locale, title, grammar_tip, pronunciation_tip) values ('7f7566e1-f570-5c82-82db-037878131bd1', 'en-US', 'Letters V to Z', 'Now you know all 26 letters. English has no tone marks, so Vietnamese names are spelled without them: Viet is V, I, E, T.', 'W is "double-you". Y is "why". In American English, Z is "zee".') on conflict (lesson_id, locale) do update set title = excluded.title, grammar_tip = excluded.grammar_tip, pronunciation_tip = excluded.pronunciation_tip, status = 'ok';
