insert into public.lessons (id, unit_id, sort_order, kind) values ('06070255-4869-5cba-be02-593aaf42c1e8', (select u.id from public.units u join public.levels l on l.id = u.level_id join public.courses c on c.id = l.course_id where c.slug = 'english' and l.code = 'pre-a1' and u.slug = 'greetings'), 1, 'lesson') on conflict (id) do update set sort_order = excluded.sort_order;
insert into public.lesson_translations (lesson_id, locale, title, grammar_tip, pronunciation_tip) values ('06070255-4869-5cba-be02-593aaf42c1e8', 'vi', 'Xin chào và tạm biệt', 'Hello dùng được với mọi người. Hi thân mật hơn, dùng với bạn bè. Goodbye lịch sự hơn Bye.', 'Đọc rõ âm cuối /d/ trong good. Người Việt hay bỏ âm này, thành "gu".') on conflict (lesson_id, locale) do update set title = excluded.title, grammar_tip = excluded.grammar_tip, pronunciation_tip = excluded.pronunciation_tip, status = 'ok';
insert into public.lesson_translations (lesson_id, locale, title, grammar_tip, pronunciation_tip) values ('06070255-4869-5cba-be02-593aaf42c1e8', 'en-US', 'Hello and goodbye', 'Use Hello with anyone. Hi is more friendly. Goodbye is more polite than Bye.', 'Say the last sound /d/ in good. Do not drop it.') on conflict (lesson_id, locale) do update set title = excluded.title, grammar_tip = excluded.grammar_tip, pronunciation_tip = excluded.pronunciation_tip, status = 'ok';
