insert into public.lessons (id, unit_id, sort_order, kind) values ('ba819bb9-467f-5991-a090-0a40319cda42', (select u.id from public.units u join public.levels l on l.id = u.level_id join public.courses c on c.id = l.course_id where c.slug = 'english' and l.code = 'pre-a1' and u.slug = 'greetings'), 3, 'lesson') on conflict (id) do update set sort_order = excluded.sort_order;
insert into public.lesson_translations (lesson_id, locale, title, grammar_tip, pronunciation_tip) values ('ba819bb9-467f-5991-a090-0a40319cda42', 'vi', 'Hỏi thăm sức khỏe', 'I''m là dạng viết gọn của I am (tôi thì, tôi là). Sau khi trả lời, hỏi lại bằng And you? để tỏ ra lịch sự.', 'Đọc rõ âm cuối /k/ trong thank và âm cuối /t/ trong great. Âm đầu của thank là /θ/: đặt đầu lưỡi giữa hai hàm răng rồi thổi hơi.') on conflict (lesson_id, locale) do update set title = excluded.title, grammar_tip = excluded.grammar_tip, pronunciation_tip = excluded.pronunciation_tip, status = 'ok';
insert into public.lesson_translations (lesson_id, locale, title, grammar_tip, pronunciation_tip) values ('ba819bb9-467f-5991-a090-0a40319cda42', 'en-US', 'How are you?', 'I''m is the short form of I am. After you answer, ask And you? to be polite.', 'Say the last sound /k/ in thank and /t/ in great. The first sound in thank is /θ/: put your tongue between your teeth and blow.') on conflict (lesson_id, locale) do update set title = excluded.title, grammar_tip = excluded.grammar_tip, pronunciation_tip = excluded.pronunciation_tip, status = 'ok';
