insert into public.lessons (id, unit_id, sort_order, kind) values ('586a2cdf-4f15-5220-96c0-df9edc2b721c', (select u.id from public.units u join public.levels l on l.id = u.level_id join public.courses c on c.id = l.course_id where c.slug = 'english' and l.code = 'pre-a1' and u.slug = 'greetings'), 4, 'lesson') on conflict (id) do update set sort_order = excluded.sort_order;
insert into public.lesson_translations (lesson_id, locale, title, grammar_tip, pronunciation_tip) values ('586a2cdf-4f15-5220-96c0-df9edc2b721c', 'vi', 'Cảm ơn, xin lỗi và lời lịch sự', 'You''re là dạng viết gọn của you are. Excuse me dùng trước khi làm phiền ai (hỏi đường, xin đi qua). I''m sorry dùng sau khi mình làm sai điều gì.', 'Đọc rõ âm cuối /z/ trong please và excuse, không đọc thành "pli". Âm cuối /s/ trong yes cũng phải nghe được.') on conflict (lesson_id, locale) do update set title = excluded.title, grammar_tip = excluded.grammar_tip, pronunciation_tip = excluded.pronunciation_tip, status = 'ok';
insert into public.lesson_translations (lesson_id, locale, title, grammar_tip, pronunciation_tip) values ('586a2cdf-4f15-5220-96c0-df9edc2b721c', 'en-US', 'Thank you, sorry, and polite words', 'You''re is the short form of you are. Say Excuse me before you ask or pass someone. Say I''m sorry after you do something wrong.', 'Say the last sound /z/ in please and excuse. Say the last sound /s/ in yes.') on conflict (lesson_id, locale) do update set title = excluded.title, grammar_tip = excluded.grammar_tip, pronunciation_tip = excluded.pronunciation_tip, status = 'ok';
