insert into public.lessons (id, unit_id, sort_order, kind) values ('607f058e-46a6-528d-9167-b2e5b5df20cf', (select u.id from public.units u join public.levels l on l.id = u.level_id join public.courses c on c.id = l.course_id where c.slug = 'english' and l.code = 'pre-a1' and u.slug = 'numbers-0-20'), 1, 'lesson') on conflict (id) do update set sort_order = excluded.sort_order;
insert into public.lesson_translations (lesson_id, locale, title, grammar_tip, pronunciation_tip) values ('607f058e-46a6-528d-9167-b2e5b5df20cf', 'vi', 'Số 0 đến 5', 'Khi đọc số điện thoại, người ta đọc từng chữ số một. Số 0 có thể đọc là zero hoặc đọc như chữ O.', 'Three bắt đầu bằng âm /θ/: đặt đầu lưỡi giữa hai hàm răng rồi thổi hơi, đừng đọc thành "tri". Five kết thúc bằng âm /v/: răng trên chạm nhẹ môi dưới.') on conflict (lesson_id, locale) do update set title = excluded.title, grammar_tip = excluded.grammar_tip, pronunciation_tip = excluded.pronunciation_tip, status = 'ok';
insert into public.lesson_translations (lesson_id, locale, title, grammar_tip, pronunciation_tip) values ('607f058e-46a6-528d-9167-b2e5b5df20cf', 'en-US', 'Numbers 0 to 5', 'To say a phone number, say each number one by one. You can say 0 as zero, or like the letter O.', 'Three starts with /θ/: put your tongue between your teeth and blow. Five ends with /v/: your top teeth touch your bottom lip.') on conflict (lesson_id, locale) do update set title = excluded.title, grammar_tip = excluded.grammar_tip, pronunciation_tip = excluded.pronunciation_tip, status = 'ok';
