insert into public.lessons (id, unit_id, sort_order, kind) values ('f2f997c0-84c7-5ed6-b301-78f8bc3f036b', (select u.id from public.units u join public.levels l on l.id = u.level_id join public.courses c on c.id = l.course_id where c.slug = 'english' and l.code = 'pre-a1' and u.slug = 'numbers-0-20'), 2, 'lesson') on conflict (id) do update set sort_order = excluded.sort_order;
insert into public.lesson_translations (lesson_id, locale, title, grammar_tip, pronunciation_tip) values ('f2f997c0-84c7-5ed6-b301-78f8bc3f036b', 'vi', 'Số 6 đến 10', 'Number + số dùng để gọi tên theo số thứ tự: number seven là "số bảy" (bàn số 7, phòng số 7).', 'Six kết thúc bằng /ks/, phải nghe được âm "x" ở cuối. Seven có âm /v/ ở giữa. Eight kết thúc bằng /t/.') on conflict (lesson_id, locale) do update set title = excluded.title, grammar_tip = excluded.grammar_tip, pronunciation_tip = excluded.pronunciation_tip, status = 'ok';
insert into public.lesson_translations (lesson_id, locale, title, grammar_tip, pronunciation_tip) values ('f2f997c0-84c7-5ed6-b301-78f8bc3f036b', 'en-US', 'Numbers 6 to 10', 'Use number + a number to name things: number seven (table number 7, room number 7).', 'Six ends with /ks/. Seven has /v/ in the middle. Eight ends with /t/.') on conflict (lesson_id, locale) do update set title = excluded.title, grammar_tip = excluded.grammar_tip, pronunciation_tip = excluded.pronunciation_tip, status = 'ok';
