insert into public.lessons (id, unit_id, sort_order, kind) values ('0527b467-2a82-541d-8ae0-c23969cbac2a', (select u.id from public.units u join public.levels l on l.id = u.level_id join public.courses c on c.id = l.course_id where c.slug = 'english' and l.code = 'pre-a1' and u.slug = 'numbers-0-20'), 3, 'lesson') on conflict (id) do update set sort_order = excluded.sort_order;
insert into public.lesson_translations (lesson_id, locale, title, grammar_tip, pronunciation_tip) values ('0527b467-2a82-541d-8ae0-c23969cbac2a', 'vi', 'Số 11 đến 15', 'Eleven và twelve là hai từ riêng. Từ 13 trở đi, số có đuôi -teen: thirteen, fourteen, fifteen.', 'Đuôi -teen đọc kéo dài "tiin" và được nhấn mạnh. Thirteen và fifteen đổi chữ so với three và five, đừng đọc thành "threeteen" hay "fiveteen".') on conflict (lesson_id, locale) do update set title = excluded.title, grammar_tip = excluded.grammar_tip, pronunciation_tip = excluded.pronunciation_tip, status = 'ok';
insert into public.lesson_translations (lesson_id, locale, title, grammar_tip, pronunciation_tip) values ('0527b467-2a82-541d-8ae0-c23969cbac2a', 'en-US', 'Numbers 11 to 15', 'Eleven and twelve are special words. From 13, the numbers end in -teen: thirteen, fourteen, fifteen.', 'Say -teen long and strong. Thirteen and fifteen change their spelling. Do not say "threeteen" or "fiveteen".') on conflict (lesson_id, locale) do update set title = excluded.title, grammar_tip = excluded.grammar_tip, pronunciation_tip = excluded.pronunciation_tip, status = 'ok';
