insert into public.lessons (id, unit_id, sort_order, kind) values ('8d360314-eda2-52eb-8f63-b5cd0da51712', (select u.id from public.units u join public.levels l on l.id = u.level_id join public.courses c on c.id = l.course_id where c.slug = 'english' and l.code = 'pre-a1' and u.slug = 'numbers-0-20'), 4, 'lesson') on conflict (id) do update set sort_order = excluded.sort_order;
insert into public.lesson_translations (lesson_id, locale, title, grammar_tip, pronunciation_tip) values ('8d360314-eda2-52eb-8f63-b5cd0da51712', 'vi', 'Số 16 đến 20', 'Sixteen, seventeen, nineteen ghép từ six, seven, nine với đuôi -teen. Eighteen chỉ có một chữ t. Twenty là số tròn chục đầu tiên có đuôi -ty.', 'Đuôi -teen kéo dài và được nhấn; đuôi -ty đọc ngắn và nhẹ. Phân biệt này rất quan trọng về sau (thirteen khác thirty). Twenty bắt đầu bằng cụm /tw/: đọc liền "tw", không chen nguyên âm.') on conflict (lesson_id, locale) do update set title = excluded.title, grammar_tip = excluded.grammar_tip, pronunciation_tip = excluded.pronunciation_tip, status = 'ok';
insert into public.lesson_translations (lesson_id, locale, title, grammar_tip, pronunciation_tip) values ('8d360314-eda2-52eb-8f63-b5cd0da51712', 'en-US', 'Numbers 16 to 20', 'Sixteen, seventeen, and nineteen are six, seven, and nine plus -teen. Eighteen has only one t. Twenty ends in -ty.', 'Say -teen long and strong. Say -ty short and weak. This matters later (thirteen and thirty). Twenty starts with /tw/: say the two sounds together.') on conflict (lesson_id, locale) do update set title = excluded.title, grammar_tip = excluded.grammar_tip, pronunciation_tip = excluded.pronunciation_tip, status = 'ok';
