insert into public.lessons (id, unit_id, sort_order, kind) values ('6c964cbc-e11e-5e3c-818d-63a43e6efd59', (select u.id from public.units u join public.levels l on l.id = u.level_id join public.courses c on c.id = l.course_id where c.slug = 'english' and l.code = 'pre-a1' and u.slug = 'name-age-origin'), 1, 'lesson') on conflict (id) do update set sort_order = excluded.sort_order;
insert into public.lesson_translations (lesson_id, locale, title, grammar_tip, pronunciation_tip) values ('6c964cbc-e11e-5e3c-818d-63a43e6efd59', 'vi', 'Bạn tên là gì?', 'What''s là dạng viết gọn của What is. Có hai cách nói tên: My name is Anna (trang trọng hơn) và I''m Anna (thông dụng hơn).', 'Nối âm: name is đọc liền thành "nei-miz". Đọc rõ âm cuối /m/ trong name và I''m.') on conflict (lesson_id, locale) do update set title = excluded.title, grammar_tip = excluded.grammar_tip, pronunciation_tip = excluded.pronunciation_tip, status = 'ok';
insert into public.lesson_translations (lesson_id, locale, title, grammar_tip, pronunciation_tip) values ('6c964cbc-e11e-5e3c-818d-63a43e6efd59', 'en-US', 'What''s your name?', 'What''s is the short form of What is. You can say your name in two ways: My name is Anna, or I''m Anna.', 'Link the words: name is sounds like "nay-miz". Say the last sound /m/ in name and I''m.') on conflict (lesson_id, locale) do update set title = excluded.title, grammar_tip = excluded.grammar_tip, pronunciation_tip = excluded.pronunciation_tip, status = 'ok';
