insert into public.lessons (id, unit_id, sort_order, kind) values ('506e5b2d-3db3-5244-92f7-4ad21f0e38ff', (select u.id from public.units u join public.levels l on l.id = u.level_id join public.courses c on c.id = l.course_id where c.slug = 'english' and l.code = 'pre-a1' and u.slug = 'name-age-origin'), 2, 'lesson') on conflict (id) do update set sort_order = excluded.sort_order;
insert into public.lesson_translations (lesson_id, locale, title, grammar_tip, pronunciation_tip) values ('506e5b2d-3db3-5244-92f7-4ad21f0e38ff', 'vi', 'Bạn bao nhiêu tuổi?', 'Tiếng Anh dùng động từ be để nói tuổi: I''m twenty (không nói I have twenty). Trả lời ngắn: Yes, I am hoặc No, I''m not. Không viết gọn thành Yes, I''m.', 'Đọc rõ âm cuối /d/ trong old và âm cuối /z/ trong years. Nối âm: years old đọc liền thành "yiơ-zôuld".') on conflict (lesson_id, locale) do update set title = excluded.title, grammar_tip = excluded.grammar_tip, pronunciation_tip = excluded.pronunciation_tip, status = 'ok';
insert into public.lesson_translations (lesson_id, locale, title, grammar_tip, pronunciation_tip) values ('506e5b2d-3db3-5244-92f7-4ad21f0e38ff', 'en-US', 'How old are you?', 'Use be to say your age: I''m twenty. Short answers: Yes, I am, or No, I''m not. Do not say Yes, I''m.', 'Say the last sound /d/ in old and /z/ in years. Link the words: years old.') on conflict (lesson_id, locale) do update set title = excluded.title, grammar_tip = excluded.grammar_tip, pronunciation_tip = excluded.pronunciation_tip, status = 'ok';
