insert into public.lessons (id, unit_id, sort_order, kind) values ('290d3589-eb24-52fa-aa4a-338316360c94', (select u.id from public.units u join public.levels l on l.id = u.level_id join public.courses c on c.id = l.course_id where c.slug = 'english' and l.code = 'pre-a1' and u.slug = 'name-age-origin'), 4, 'lesson') on conflict (id) do update set sort_order = excluded.sort_order;
insert into public.lesson_translations (lesson_id, locale, title, grammar_tip, pronunciation_tip) values ('290d3589-eb24-52fa-aa4a-338316360c94', 'vi', 'Làm quen với người mới', 'That''s là dạng viết gọn của That is. Ôn lại: câu hỏi với be luôn bắt đầu bằng Are you...? và trả lời ngắn bằng Yes, I am hoặc No, I''m not.', 'Đọc rõ âm cuối /t/ trong right và /ts/ trong that''s. Lên giọng ở cuối câu hỏi Are you new here? và ở từ Really?') on conflict (lesson_id, locale) do update set title = excluded.title, grammar_tip = excluded.grammar_tip, pronunciation_tip = excluded.pronunciation_tip, status = 'ok';
insert into public.lesson_translations (lesson_id, locale, title, grammar_tip, pronunciation_tip) values ('290d3589-eb24-52fa-aa4a-338316360c94', 'en-US', 'Getting to know someone new', 'That''s is the short form of That is. Remember: questions with be start with Are you...? Short answers are Yes, I am, or No, I''m not.', 'Say the last sound /t/ in right and /ts/ in that''s. Your voice goes up at the end of Are you new here? and Really?') on conflict (lesson_id, locale) do update set title = excluded.title, grammar_tip = excluded.grammar_tip, pronunciation_tip = excluded.pronunciation_tip, status = 'ok';
