insert into public.lessons (id, unit_id, sort_order, kind) values ('44decd11-1911-56a3-ae88-312f213fec51', (select u.id from public.units u join public.levels l on l.id = u.level_id join public.courses c on c.id = l.course_id where c.slug = 'english' and l.code = 'pre-a1' and u.slug = 'things-around-us'), 1, 'lesson') on conflict (id) do update set sort_order = excluded.sort_order;
insert into public.lesson_translations (lesson_id, locale, title, grammar_tip, pronunciation_tip) values ('44decd11-1911-56a3-ae88-312f213fec51', 'vi', 'Đây là một...', 'This chỉ vật ở gần người nói. Trước danh từ đếm được số ít phải có a: This is a book. Nếu đã có my hoặc your thì không dùng a nữa: This is my phone.', 'This bắt đầu bằng âm /ð/: đặt đầu lưỡi giữa hai hàm răng và rung dây thanh, đừng đọc thành "đít". Nối âm: this is đọc liền thành "thi-siz".') on conflict (lesson_id, locale) do update set title = excluded.title, grammar_tip = excluded.grammar_tip, pronunciation_tip = excluded.pronunciation_tip, status = 'ok';
insert into public.lesson_translations (lesson_id, locale, title, grammar_tip, pronunciation_tip) values ('44decd11-1911-56a3-ae88-312f213fec51', 'en-US', 'This is a...', 'Use this for a thing near you. Put a before one thing: This is a book. Do not use a after my or your: This is my phone.', 'This starts with /ð/: put your tongue between your teeth and use your voice. Link the words: this is.') on conflict (lesson_id, locale) do update set title = excluded.title, grammar_tip = excluded.grammar_tip, pronunciation_tip = excluded.pronunciation_tip, status = 'ok';
