insert into public.lessons (id, unit_id, sort_order, kind) values ('a122ebb2-bb7e-5355-bb8a-d1f8ef127463', (select u.id from public.units u join public.levels l on l.id = u.level_id join public.courses c on c.id = l.course_id where c.slug = 'english' and l.code = 'pre-a1' and u.slug = 'things-around-us'), 2, 'lesson') on conflict (id) do update set sort_order = excluded.sort_order;
insert into public.lesson_translations (lesson_id, locale, title, grammar_tip, pronunciation_tip) values ('a122ebb2-bb7e-5355-bb8a-d1f8ef127463', 'vi', 'Kia là một...', 'That chỉ vật ở xa người nói. Dùng an thay cho a trước từ bắt đầu bằng âm nguyên âm (a, e, i, o, u): an apple, an egg, an umbrella.', 'Nối âm: an apple đọc liền thành "ơ-náp-pồ", âm /n/ dính sang từ sau. That kết thúc bằng /t/, đừng bỏ.') on conflict (lesson_id, locale) do update set title = excluded.title, grammar_tip = excluded.grammar_tip, pronunciation_tip = excluded.pronunciation_tip, status = 'ok';
insert into public.lesson_translations (lesson_id, locale, title, grammar_tip, pronunciation_tip) values ('a122ebb2-bb7e-5355-bb8a-d1f8ef127463', 'en-US', 'That is an...', 'Use that for a thing far from you. Use an, not a, before a vowel sound (a, e, i, o, u): an apple, an egg, an umbrella.', 'Link the words: an apple sounds like "a-napple". That ends with /t/. Do not drop it.') on conflict (lesson_id, locale) do update set title = excluded.title, grammar_tip = excluded.grammar_tip, pronunciation_tip = excluded.pronunciation_tip, status = 'ok';
