insert into public.lessons (id, unit_id, sort_order, kind) values ('9cddb0f3-f9e1-53ea-b19c-dc94225bccbf', (select u.id from public.units u join public.levels l on l.id = u.level_id join public.courses c on c.id = l.course_id where c.slug = 'english' and l.code = 'pre-a1' and u.slug = 'things-around-us'), 3, 'lesson') on conflict (id) do update set sort_order = excluded.sort_order;
insert into public.lesson_translations (lesson_id, locale, title, grammar_tip, pronunciation_tip) values ('9cddb0f3-f9e1-53ea-b19c-dc94225bccbf', 'vi', 'Nó là...', 'Khi trả lời câu hỏi What''s this? hoặc What''s that?, dùng It để thay cho vật vừa nhắc đến: It''s a key. It''s là dạng viết gọn của It is.', 'It''s kết thúc bằng /ts/: phải nghe được cả âm "t" lẫn âm "x". Table và chair: đọc rõ âm cuối /l/ và /r/.') on conflict (lesson_id, locale) do update set title = excluded.title, grammar_tip = excluded.grammar_tip, pronunciation_tip = excluded.pronunciation_tip, status = 'ok';
insert into public.lesson_translations (lesson_id, locale, title, grammar_tip, pronunciation_tip) values ('9cddb0f3-f9e1-53ea-b19c-dc94225bccbf', 'en-US', 'It is...', 'To answer What''s this? or What''s that?, use It for the thing: It''s a key. It''s is the short form of It is.', 'It''s ends with /ts/. Say both sounds. Say the last sounds in table and chair.') on conflict (lesson_id, locale) do update set title = excluded.title, grammar_tip = excluded.grammar_tip, pronunciation_tip = excluded.pronunciation_tip, status = 'ok';
