insert into public.lessons (id, unit_id, sort_order, kind) values ('923cf1ac-1601-59fe-87fa-194af50f6b9e', (select u.id from public.units u join public.levels l on l.id = u.level_id join public.courses c on c.id = l.course_id where c.slug = 'english' and l.code = 'pre-a1' and u.slug = 'things-around-us'), 4, 'lesson') on conflict (id) do update set sort_order = excluded.sort_order;
insert into public.lesson_translations (lesson_id, locale, title, grammar_tip, pronunciation_tip) values ('923cf1ac-1601-59fe-87fa-194af50f6b9e', 'vi', 'Cái này hay cái kia?', 'Or (hay, hoặc) dùng để hỏi lựa chọn giữa hai thứ: Is this a cup or a pen? Câu trả lời nêu thẳng một trong hai, không trả lời Yes hoặc No.', 'Cup kết thúc bằng /p/ và watch kết thúc bằng /tʃ/ ("ch"): phải bật hơi ở cuối. Trong câu hỏi có or, lên giọng ở vế đầu và xuống giọng ở vế sau.') on conflict (lesson_id, locale) do update set title = excluded.title, grammar_tip = excluded.grammar_tip, pronunciation_tip = excluded.pronunciation_tip, status = 'ok';
insert into public.lesson_translations (lesson_id, locale, title, grammar_tip, pronunciation_tip) values ('923cf1ac-1601-59fe-87fa-194af50f6b9e', 'en-US', 'This or that?', 'Use or to ask about two things: Is this a cup or a pen? Answer with one of the two things, not with Yes or No.', 'Cup ends with /p/ and watch ends with /tʃ/. Say the last sound. In a question with or, your voice goes up on the first thing and down on the second.') on conflict (lesson_id, locale) do update set title = excluded.title, grammar_tip = excluded.grammar_tip, pronunciation_tip = excluded.pronunciation_tip, status = 'ok';
