insert into public.lessons (id, unit_id, sort_order, kind) values ('2c22d334-b5c0-57fa-ba4b-9cc721177119', (select u.id from public.units u join public.levels l on l.id = u.level_id join public.courses c on c.id = l.course_id where c.slug = 'english' and l.code = 'pre-a1' and u.slug = 'colors-and-descriptions'), 1, 'lesson') on conflict (id) do update set sort_order = excluded.sort_order;
insert into public.lesson_translations (lesson_id, locale, title, grammar_tip, pronunciation_tip) values ('2c22d334-b5c0-57fa-ba4b-9cc721177119', 'vi', 'Màu sắc cơ bản', 'Hỏi màu bằng What color is it? Trả lời bằng It''s + màu. Tính từ chỉ màu đứng sau is và không cần a: It''s red, không nói It''s a red.', 'Red và green có âm /r/: cong lưỡi lên, không chạm vòm miệng, không rung. Blue và yellow có âm /l/: đầu lưỡi chạm vào chân răng trên. Đừng nhầm hai âm này.') on conflict (lesson_id, locale) do update set title = excluded.title, grammar_tip = excluded.grammar_tip, pronunciation_tip = excluded.pronunciation_tip, status = 'ok';
insert into public.lesson_translations (lesson_id, locale, title, grammar_tip, pronunciation_tip) values ('2c22d334-b5c0-57fa-ba4b-9cc721177119', 'en-US', 'Basic colors', 'Ask What color is it? Answer with It''s + a color. Do not use a before a color word: It''s red.', 'Red and green have /r/: curl your tongue and do not touch the top of your mouth. Blue and yellow have /l/: your tongue touches behind your top teeth.') on conflict (lesson_id, locale) do update set title = excluded.title, grammar_tip = excluded.grammar_tip, pronunciation_tip = excluded.pronunciation_tip, status = 'ok';
