insert into public.lessons (id, unit_id, sort_order, kind) values ('fafecf92-3d18-5946-abb5-4a785fa7e963', (select u.id from public.units u join public.levels l on l.id = u.level_id join public.courses c on c.id = l.course_id where c.slug = 'english' and l.code = 'pre-a1' and u.slug = 'colors-and-descriptions'), 2, 'lesson') on conflict (id) do update set sort_order = excluded.sort_order;
insert into public.lesson_translations (lesson_id, locale, title, grammar_tip, pronunciation_tip) values ('fafecf92-3d18-5946-abb5-4a785fa7e963', 'vi', 'Thêm màu sắc', 'Dùng or để hỏi lựa chọn giữa hai màu: Is it black or white? Tính từ chỉ màu không đổi dạng dù chủ ngữ là gì.', 'Black kết thúc bằng /k/ và white kết thúc bằng /t/: bật nhẹ âm cuối. Brown có cụm /br/: đọc liền hai phụ âm, không chen nguyên âm thành "bờ-rao".') on conflict (lesson_id, locale) do update set title = excluded.title, grammar_tip = excluded.grammar_tip, pronunciation_tip = excluded.pronunciation_tip, status = 'ok';
insert into public.lesson_translations (lesson_id, locale, title, grammar_tip, pronunciation_tip) values ('fafecf92-3d18-5946-abb5-4a785fa7e963', 'en-US', 'More colors', 'Use or to ask about two colors: Is it black or white? Color words never change their form.', 'Black ends with /k/ and white ends with /t/. Say the last sound. Brown starts with /br/: say the two sounds together.') on conflict (lesson_id, locale) do update set title = excluded.title, grammar_tip = excluded.grammar_tip, pronunciation_tip = excluded.pronunciation_tip, status = 'ok';
