insert into public.lessons (id, unit_id, sort_order, kind) values ('748f710a-729f-57d1-aca4-aece213fdd35', (select u.id from public.units u join public.levels l on l.id = u.level_id join public.courses c on c.id = l.course_id where c.slug = 'english' and l.code = 'pre-a1' and u.slug = 'colors-and-descriptions'), 3, 'lesson') on conflict (id) do update set sort_order = excluded.sort_order;
insert into public.lesson_translations (lesson_id, locale, title, grammar_tip, pronunciation_tip) values ('748f710a-729f-57d1-aca4-aece213fdd35', 'vi', 'To và nhỏ, dài và ngắn', 'Very (rất) đứng trước tính từ để nhấn mạnh: very big. Thứ tự là chủ ngữ + is + very + tính từ: This table is very big.', 'Small bắt đầu bằng cụm /sm/ và kết thúc bằng /l/: đừng đọc thành "sờ-mo". Long có âm /l/ ở đầu, short kết thúc bằng /t/. Very có âm /v/ và /r/: răng trên chạm môi dưới, rồi cong lưỡi.') on conflict (lesson_id, locale) do update set title = excluded.title, grammar_tip = excluded.grammar_tip, pronunciation_tip = excluded.pronunciation_tip, status = 'ok';
insert into public.lesson_translations (lesson_id, locale, title, grammar_tip, pronunciation_tip) values ('748f710a-729f-57d1-aca4-aece213fdd35', 'en-US', 'Big and small, long and short', 'Put very before a describing word to make it stronger: very big. The order is: This table is very big.', 'Small starts with /sm/ and ends with /l/. Long starts with /l/. Short ends with /t/. Very has /v/ and /r/.') on conflict (lesson_id, locale) do update set title = excluded.title, grammar_tip = excluded.grammar_tip, pronunciation_tip = excluded.pronunciation_tip, status = 'ok';
