insert into public.lessons (id, unit_id, sort_order, kind) values ('3ad30b28-122e-5755-8aab-0e7dfc4852d5', (select u.id from public.units u join public.levels l on l.id = u.level_id join public.courses c on c.id = l.course_id where c.slug = 'english' and l.code = 'pre-a1' and u.slug = 'colors-and-descriptions'), 4, 'lesson') on conflict (id) do update set sort_order = excluded.sort_order;
insert into public.lesson_translations (lesson_id, locale, title, grammar_tip, pronunciation_tip) values ('3ad30b28-122e-5755-8aab-0e7dfc4852d5', 'vi', 'Mô tả đồ vật', 'Tính từ có hai vị trí: sau is (My cup is clean) hoặc trước danh từ (a beautiful bag). Trong tiếng Anh tính từ đứng trước danh từ, ngược với tiếng Việt. But (nhưng) nối hai ý trái ngược.', 'Clean bắt đầu bằng cụm /kl/ và kết thúc bằng /n/. Dirty có âm /r/ ở giữa: cong lưỡi. Beautiful có ba âm tiết, nhấn vào âm đầu: BEAU-ti-ful.') on conflict (lesson_id, locale) do update set title = excluded.title, grammar_tip = excluded.grammar_tip, pronunciation_tip = excluded.pronunciation_tip, status = 'ok';
insert into public.lesson_translations (lesson_id, locale, title, grammar_tip, pronunciation_tip) values ('3ad30b28-122e-5755-8aab-0e7dfc4852d5', 'en-US', 'Describing things', 'A describing word goes after is (My cup is clean) or before the thing (a beautiful bag). Use but to join two different ideas.', 'Clean starts with /kl/ and ends with /n/. Dirty has /r/ in the middle. Beautiful has three parts. Say the first part strong: BEAU-ti-ful.') on conflict (lesson_id, locale) do update set title = excluded.title, grammar_tip = excluded.grammar_tip, pronunciation_tip = excluded.pronunciation_tip, status = 'ok';
insert into public.words (id, course_id, lemma, part_of_speech, pronunciation, level_tag) values ('bff40f87-7d45-59bb-82ab-d1d4fa983c4a', (select id from public.courses where slug = 'english'), 'beautiful', 'adjective', '/ˈbjutəfəɫ/', 'A1') on conflict (id) do update set pronunciation = excluded.pronunciation, level_tag = excluded.level_tag;
